import React from 'react';
import AgeSelect from './components/AgeSelect';

type FieldType = {
  username?: string;
  password?: number;
  remember?: boolean;
};

const App: React.FC = () => {
  const [form] = Form.useForm();
  useMount(() => {
    form.setFieldsValue({
      username: '\u674E\u5C9A\u6E05',
    });
  });
  return (
    <LForm<FieldType>
      variant="filled"
      onValuesChange={(currentName, currentVal) => {}}
      formItemBottom={16}
      submitter={{
        isEnterSubmit: true,
        position: 'center',
        onReset(event) {
          console.log('onReset');
        },
        onSubmit: (vals) => {
          console.log('onSubmit', vals);
        },
      }}
      labelWidth={100}
      autoComplete="off"
      rootClassName="asdasd"
      form={form}
      name="basic-2025"
      initialValues={{
        remember: true,
        username: '56165',
      }}
      onFinish={(values) => {
        console.log('====onFinish====', values);
        return new Promise((resolve) => {
          setTimeout(() => {
            resolve(true);
          }, 2000);
        });
      }}
      // onValuesChange={(changedValues, allValues) => {
      //   console.log('===onValuesChange===>', changedValues, allValues);
      // }}
      // onFieldsChange={(changedFields, allFields) => {
      //   console.log('===onFieldsChange===>', changedFields, allFields);
      // }}
    >
      <LFormItem
        labelCol={{ span: 8 }}
        wrapperCol={{ span: 16 }}
        // noStyle
        // hidden
        // extra={111}
        // help={999}

        // colon={false}
        // label={null}
        // shouldUpdate  //\u8981\u6CE8\u610F Form.Item \u91CC\u5305\u88F9\u7684\u5B50\u7EC4\u4EF6\u5FC5\u987B\u7531\u51FD\u6570\u8FD4\u56DE
        // layout='vertical'
        // rootClassName='1321'
        // labelCol={{
        //   flex: '0 0 100px',
        // }}
        getValueFromEvent={(e) => {
          // \u53EA\u5728\u7528\u6237\u64CD\u4F5C\u6709\u6548
          // console.log('===getValueFromEvent-1===>', e);
          return e.target.value;
        }}
        normalize={(v, pv, s) => {
          // \u53EA\u5728\u7528\u6237\u64CD\u4F5C\u6709\u6548
          // console.log('===normalize-2===>', v);
          return v;
        }}
        getValueProps={(value) => {
          //\u6BCF\u6B21\u521D\u59CB\u5316\u6216\u8005\u91CD\u65B0\u6E32\u67D3\u90FD\u6709\u6548
          // console.log('===getValueProps-3===>', value);
          return { value };
        }}
        label="Username"
        name="username"
        rules={[{ required: true, message: 'Please input your username!' }]}
        validateDebounce={200}
        // required
      >
        <Input />
      </LFormItem>

      <LFormItem
        required
        label="Password"
        name="password"
        rules={[{ required: true, message: 'Please input your password!' }]}
        // contentBefore={<div>999</div>}
        // contentAfter={<Button>123</Button>}
        // alignItems="center"
      >
        <Input.Password />
      </LFormItem>

      <LFormItem
        contentWrapperProps={{
          className: '123',
        }}
        name="switch"
        label={'Switch'}
        valuePropName="checked"
        contentBefore={<div>999</div>}
        contentAfter={<Button>123</Button>}
      >
        <Switch></Switch>
      </LFormItem>

      <LFormItem name="age" label={'\u6D4B\u8BD5'} dependencies={['switch']}>
        <AgeSelect></AgeSelect>
      </LFormItem>
    </LForm>
  );
};

export default App;

